macro_rules! Py_CLEAR__20 {
    ($op:expr) => {
        loop {
            let _tmp_op_ptr: *mut *mut _symtable_entry = core::ptr::addr_of_mut!($op);
            let _tmp_old_op: *mut _symtable_entry = unsafe { *_tmp_op_ptr };
            if !_tmp_old_op.is_null() {
                unsafe {
                    *_tmp_op_ptr = core::ptr::null_mut::<_symtable_entry>();
                }
                Py_DECREF__2!(_tmp_old_op);
            }
            if true {
                break;
            }
        }
    };
}

